// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public {
        c = new ReentrancyDAO();
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        depositAmount = bound(depositAmount, 1, 1_000_000 ether);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        Receiver helper = new Receiver();
        address adversary = address(helper);

        vm.deal(adversary, depositAmount);
        vm.prank(adversary);
        c.deposit{value: depositAmount}();

        vm.prank(adversary);
        c.withdrawAll();

        uint256 balanceBeforeSecond = address(c).balance;
        bool secondOk;
        vm.prank(adversary);
        try c.withdrawAll() { secondOk = true; } catch { secondOk = false; }

        uint256 balanceAfterSecond = address(c).balance;
        assertTrue(balanceAfterSecond == balanceBeforeSecond);
    }
}

contract Receiver {
    receive() external payable {}
}
